package com.comfymobile.app;

import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

/** Durable state shared by the foreground worker and the visible UI. */
final class BatchStore {
 private static BatchStore instance;
 static synchronized BatchStore open(File directory)throws Exception{if(instance==null)instance=new BatchStore(new File(directory,"native-batches.json"));return instance;}
 private final File file;private JSONObject root;
 BatchStore(File file)throws Exception{this.file=file;root=file.exists()?new JSONObject(new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8)):new JSONObject();if(!root.has("jobs"))root.put("jobs",new JSONObject());if(!root.has("images"))root.put("images",new JSONArray());if(!root.has("deleted"))root.put("deleted",new JSONArray());}
 private static JSONObject copy(JSONObject x)throws JSONException{return new JSONObject(x.toString());}
 private void flush()throws Exception{root.put("revision",root.optLong("revision")+1);File temp=new File(file.getPath()+".tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(root.toString().getBytes(StandardCharsets.UTF_8));out.getFD().sync();}try{Files.move(temp.toPath(),file.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(temp.toPath(),file.toPath(),StandardCopyOption.REPLACE_EXISTING);}}
 synchronized JSONObject job(String mode)throws Exception{JSONObject j=root.getJSONObject("jobs").optJSONObject(mode);return j==null?null:copy(j);}
 static boolean terminal(String task){return Arrays.asList("idle","done","error","lost","cancelled","paused").contains(task);}
 synchronized boolean hasWork()throws Exception{for(String mode:new String[]{"text","image","anime"}){JSONObject j=job(mode);if(j!=null&&!terminal(j.optString("task")))return true;}return false;}
 synchronized void start(JSONObject job)throws Exception{String mode=job.getString("mode");if(!mode.equals("text")&&!mode.equals("image")&&!mode.equals("anime"))throw new IOException("生成类型无效");JSONObject old=job(mode);if(old!=null&&!terminal(old.optString("task")))throw new IOException("这个工作流已有运行中的批次");root.getJSONObject("jobs").put(mode,copy(job));flush();}
 synchronized void control(String mode,String id,String action)throws Exception{JSONObject j=job(mode);if(j==null||!j.getJSONObject("batch").getString("id").equals(id))throw new IOException("批次已改变，请刷新后重试");JSONObject b=j.getJSONObject("batch");if(action.equals("cancel")){if(Arrays.asList("done","error","cancelled").contains(j.optString("task")))return;b.put("cancelRequested",true);j.put("task","cancelling");j.put("stage","正在取消整个批次");}else if(action.equals("pause")){if(terminal(j.optString("task")))return;b.put("pauseRequested",true);j.put("stage","当前图片完成后暂停后续任务");}else if(action.equals("resume")){if(!j.optString("task").equals("paused")||b.optBoolean("cancelRequested"))return;b.put("pauseRequested",false);j.put("task","between");j.put("stage","继续本批次");}else throw new IOException("操作无效");b.put("controlVersion",b.optInt("controlVersion")+1);j.put("retryAt",0);root.getJSONObject("jobs").put(mode,j);flush();}
 synchronized void save(JSONObject j)throws Exception{String mode=j.getString("mode");JSONObject old=job(mode);if(old==null||!old.getJSONObject("batch").getString("id").equals(j.getJSONObject("batch").getString("id")))return;JSONObject b=j.getJSONObject("batch"),previous=old.getJSONObject("batch");int version=b.optInt("controlVersion");b.put("cancelRequested",previous.optBoolean("cancelRequested"));b.put("pauseRequested",previous.optBoolean("pauseRequested"));b.put("controlVersion",previous.optInt("controlVersion"));if(previous.optInt("controlVersion")>version&&old.optString("task").equals("between")&&j.optString("task").equals("paused"))j.put("task","between");if(b.optBoolean("cancelRequested")&&!Arrays.asList("done","cancelled","error").contains(j.optString("task")))j.put("task","cancelling");j.put("images",withoutDeleted(j.optJSONArray("images")));root.getJSONObject("jobs").put(mode,copy(j));flush();}
 private JSONArray withoutDeleted(JSONArray images)throws Exception{Set<String> deleted=new HashSet<>();JSONArray tombstones=root.getJSONArray("deleted");for(int i=0;i<tombstones.length();i++)deleted.add(tombstones.getString(i));JSONArray result=new JSONArray();if(images!=null)for(int i=0;i<images.length();i++)if(!deleted.contains(images.getJSONObject(i).optString("id")))result.put(images.getJSONObject(i));return result;}
 synchronized void image(JSONObject item)throws Exception{JSONArray all=root.getJSONArray("images");for(int i=0;i<all.length();i++)if(all.getJSONObject(i).getString("key").equals(item.getString("key")))return;all.put(item);root.put("images",withoutDeleted(all));flush();}
 synchronized JSONObject imageForKey(String key)throws Exception{JSONArray all=root.getJSONArray("images");for(int i=0;i<all.length();i++)if(all.getJSONObject(i).getString("key").equals(key))return copy(all.getJSONObject(i));return null;}
 synchronized void progress(String pid,int value,int max,String stage)throws Exception{for(String mode:new String[]{"text","image","anime"}){JSONObject j=job(mode);if(j!=null&&pid.equals(j.optString("promptId"))&&!BatchStore.terminal(j.optString("task"))&&!j.getJSONObject("batch").optBoolean("cancelRequested")){if(max>0)j.put("progress",Math.round(value*100f/max));else j.put("progress",JSONObject.NULL);j.put("stage",stage);root.getJSONObject("jobs").put(mode,j);flush();}}}
 synchronized void deleteImages(JSONArray ids)throws Exception{JSONArray deleted=root.getJSONArray("deleted");for(int i=0;i<ids.length();i++)deleted.put(ids.getString(i));root.put("images",withoutDeleted(root.getJSONArray("images")));for(String mode:new String[]{"text","image","anime"}){JSONObject j=root.getJSONObject("jobs").optJSONObject(mode);if(j!=null)j.put("images",withoutDeleted(j.optJSONArray("images")));}flush();}
 synchronized JSONObject snapshot()throws Exception{JSONObject result=copy(root);result.remove("deleted");JSONObject jobs=result.getJSONObject("jobs");for(String mode:new String[]{"text","image","anime"}){JSONObject j=jobs.optJSONObject(mode);if(j!=null){j.remove("bearer");j.remove("clientId");j.remove("upload1");j.remove("upload2");j.remove("retryAt");j.remove("remotePlan");if(!j.has("promptId"))j.put("promptId",JSONObject.NULL);}}return result;}
}
